def test_review_queue_apply_tool_contract():
    repo = copy_repo("review-queue-apply-tool")
    seed_pending_review_queue_items(repo, count=3)
    forms_result = run_cmd(
        repo,
        [
            "rtk",
            "bash",
            "tools/knowledge-index-plan.sh",
            "--section",
            "review-queue",
            "--queue-forms-jsonl",
            "--queue-type",
            "ai-human-review",
            "--queue-owner",
            "leiwenjun",
            "--queue-limit",
            "3",
        ],
    )
    parse_errors = []
    forms = []
    for line in forms_result["stdout"].splitlines():
        if not line.strip():
            continue
        try:
            forms.append(json.loads(line))
        except Exception as exc:
            parse_errors.append(str(exc))
    if len(forms) < 3:
        expect(False, "review-queue-apply-tool-contract", "review queue apply validates and applies filled forms without owner-gate mutation", {"setup_error": "expected at least three forms", "parse_errors": parse_errors, "stdout": forms_result["stdout"][:1000]}, repo)
        return

    temp_root = pathlib.Path(tempfile.mkdtemp(prefix="kh-regression-review-queue-apply-"))
    temp_roots.append(temp_root)
    accept_form = dict(forms[0])
    accept_form.update({
        "human_reviewed_by": "regression-fixture-human",
        "human_reviewed_at": today.isoformat(),
        "review_basis": "Regression fixture accepted this AI review record.",
        "review_decision": "accept-as-review-record",
    })
    needs_edits_form = dict(forms[1])
    needs_edits_form.update({
        "human_reviewed_by": "regression-fixture-human",
        "human_reviewed_at": today.isoformat(),
        "review_basis": "Regression fixture keeps this item open for edits.",
        "review_decision": "needs-edits",
    })
    forbidden_form = dict(accept_form)
    forbidden_form["owner_decision"] = "approved"
    stale_date_form = dict(accept_form)
    stale_date_form["human_reviewed_at"] = "2000-01-01"
    hash_mismatch_form = dict(accept_form)
    hash_mismatch_form["content_sha256"] = "0" * 64
    archive_only_form = dict(forms[2])
    archive_only_form.update({
        "human_reviewed_by": "regression-fixture-human",
        "human_reviewed_at": today.isoformat(),
        "review_basis": "Regression fixture records archive-only without changing lifecycle.",
        "review_decision": "archive-only",
    })

    accept_path = temp_root / "accept.jsonl"
    needs_edits_path = temp_root / "needs-edits.jsonl"
    forbidden_path = temp_root / "forbidden.jsonl"
    stale_date_path = temp_root / "stale-date.jsonl"
    hash_mismatch_path = temp_root / "hash-mismatch.jsonl"
    archive_only_path = temp_root / "archive-only.jsonl"
    accept_path.write_text(json.dumps(accept_form, ensure_ascii=False, separators=(",", ":")) + "\n")
    needs_edits_path.write_text(json.dumps(needs_edits_form, ensure_ascii=False, separators=(",", ":")) + "\n")
    forbidden_path.write_text(json.dumps(forbidden_form, ensure_ascii=False, separators=(",", ":")) + "\n")
    stale_date_path.write_text(json.dumps(stale_date_form, ensure_ascii=False, separators=(",", ":")) + "\n")
    hash_mismatch_path.write_text(json.dumps(hash_mismatch_form, ensure_ascii=False, separators=(",", ":")) + "\n")
    archive_only_path.write_text(json.dumps(archive_only_form, ensure_ascii=False, separators=(",", ":")) + "\n")

    before_status_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-status.sh", "--strict", "--json", "--as-of", today.isoformat()])
    dry_run_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-review-queue-apply.sh", "--forms", str(accept_path), "--dry-run", "--json"])
    forbidden_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-review-queue-apply.sh", "--forms", str(forbidden_path), "--dry-run", "--json"])
    stale_date_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-review-queue-apply.sh", "--forms", str(stale_date_path), "--dry-run", "--json"])
    hash_mismatch_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-review-queue-apply.sh", "--forms", str(hash_mismatch_path), "--dry-run", "--json"])
    archive_only_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-review-queue-apply.sh", "--forms", str(archive_only_path), "--dry-run", "--json"])
    apply_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-review-queue-apply.sh", "--forms", str(accept_path), "--apply", "--json"])
    after_accept_status_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-status.sh", "--strict", "--json", "--as-of", today.isoformat()])
    review_body_path = repo / str(accept_form.get("path", ""))
    original_review_body = review_body_path.read_text()
    try:
        review_body_path.write_text(original_review_body + "\n<!-- regression review content drift -->\n")
        drift_status_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-status.sh", "--strict", "--json", "--as-of", today.isoformat()])
        drift_check_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-check.sh", "--dry-run", "--json", "--diagnostics", "--as-of", today.isoformat()])
    finally:
        review_body_path.write_text(original_review_body)
    needs_edits_apply_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-review-queue-apply.sh", "--forms", str(needs_edits_path), "--apply", "--json"])
    after_needs_edits_status_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-status.sh", "--strict", "--json", "--as-of", today.isoformat()])
    archive_only_apply_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-review-queue-apply.sh", "--forms", str(archive_only_path), "--apply", "--json"])
    after_archive_status_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-status.sh", "--strict", "--json", "--as-of", today.isoformat()])
    archive_review_body_path = repo / str(archive_only_form.get("path", ""))
    original_archive_review_body = archive_review_body_path.read_text()
    try:
        archive_review_body_path.write_text(original_archive_review_body + "\n<!-- regression terminal review content drift -->\n")
        archive_drift_status_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-status.sh", "--strict", "--json", "--as-of", today.isoformat()])
        archive_drift_check_result = run_cmd(repo, ["rtk", "bash", "tools/knowledge-check.sh", "--dry-run", "--json", "--diagnostics", "--as-of", today.isoformat()])
    finally:
        archive_review_body_path.write_text(original_archive_review_body)

    payloads = {}
    for name, result in [
        ("before", before_status_result),
        ("dry_run", dry_run_result),
        ("forbidden", forbidden_result),
        ("stale_date", stale_date_result),
        ("hash_mismatch", hash_mismatch_result),
        ("archive_only", archive_only_result),
        ("apply", apply_result),
        ("after_accept", after_accept_status_result),
        ("drift_status", drift_status_result),
        ("drift_check", drift_check_result),
        ("needs_edits_apply", needs_edits_apply_result),
        ("after_needs_edits", after_needs_edits_status_result),
        ("archive_only_apply", archive_only_apply_result),
        ("after_archive", after_archive_status_result),
        ("archive_drift_status", archive_drift_status_result),
        ("archive_drift_check", archive_drift_check_result),
    ]:
        try:
            payloads[name] = json.loads(result["stdout"])
        except Exception as exc:
            payloads[name] = {}
            parse_errors.append(f"{name}: {exc}")

    def pending_count(name):
        return int(payloads.get(name, {}).get("review_queues", {}).get("summary", {}).get("total_pending_count", -1))

    forbidden_codes = [
        row.get("code")
        for row in payloads.get("forbidden", {}).get("diagnostics", [])
        if isinstance(row, dict)
    ]
    stale_date_codes = [
        row.get("code")
        for row in payloads.get("stale_date", {}).get("diagnostics", [])
        if isinstance(row, dict)
    ]
    hash_mismatch_codes = [
        row.get("code")
        for row in payloads.get("hash_mismatch", {}).get("diagnostics", [])
        if isinstance(row, dict)
    ]
    items_by_id = {}
    for line in (repo / "registry" / "items.jsonl").read_text().splitlines():
        if not line.strip():
            continue
        item = json.loads(line)
        items_by_id[item.get("id")] = item
    accept_item_id = accept_form.get("id")
    needs_edits_item_id = needs_edits_form.get("id")
    archive_only_item_id = archive_only_form.get("id")
    accept_item = items_by_id.get(accept_item_id, {})
    needs_edits_item = items_by_id.get(needs_edits_item_id, {})
    archive_only_item = items_by_id.get(archive_only_item_id, {})
    archive_drift_rows = payloads.get("archive_drift_status", {}).get("review_queues", {}).get("ai_generated_pending", [])

    expect(
        forms_result["exit_code"] == 0
        and len(forms) >= 3
        and not parse_errors
        and all(form.get("schema_version") == 2 for form in forms)
        and all(len(form.get("content_sha256", "")) == 64 for form in forms)
        and before_status_result["exit_code"] != 0
        and pending_count("before") >= 3
        and dry_run_result["exit_code"] == 0
        and payloads.get("dry_run", {}).get("status") == "planned"
        and payloads.get("dry_run", {}).get("applied") is False
        and forbidden_result["exit_code"] != 0
        and "forbidden-owner-field" in forbidden_codes
        and stale_date_result["exit_code"] != 0
        and "human-reviewed-at-before-created-at" in stale_date_codes
        and hash_mismatch_result["exit_code"] != 0
        and "content-sha256-mismatch" in hash_mismatch_codes
        and archive_only_result["exit_code"] == 0
        and payloads.get("archive_only", {}).get("planned_updates", [{}])[0].get("status_before")
            == payloads.get("archive_only", {}).get("planned_updates", [{}])[0].get("status_after")
        and payloads.get("archive_only", {}).get("planned_updates", [{}])[0].get("lifecycle_mutation") is False
        and apply_result["exit_code"] == 0
        and payloads.get("apply", {}).get("status") == "applied"
        and pending_count("after_accept") == pending_count("before") - 1
        and accept_item.get("human_reviewed_by") == "regression-fixture-human"
        and accept_item.get("human_review_decision") == "accept-as-review-record"
        and accept_item.get("human_review_content_sha256") == accept_form.get("content_sha256")
        and accept_item.get("review_status") == "human-reviewed-accepted"
        and pending_count("drift_status") == pending_count("before")
        and drift_check_result["exit_code"] != 0
        and "human review content drift" in drift_check_result["stdout"]
        and needs_edits_apply_result["exit_code"] == 0
        and needs_edits_item.get("human_review_decision") == "needs-edits"
        and needs_edits_item.get("review_status") == "human-review-needs-edits"
        and pending_count("after_needs_edits") == pending_count("after_accept")
        and any(
            blocker.get("id") == "review-queue-pending-product"
            for blocker in payloads.get("after_needs_edits", {}).get("strict_blockers", [])
        )
        and archive_only_apply_result["exit_code"] == 0
        and payloads.get("archive_only_apply", {}).get("status") == "applied"
        and archive_only_item.get("status") == archive_only_form.get("read_only_context", {}).get("registry_status")
        and archive_only_item.get("human_review_decision") == "archive-only"
        and archive_only_item.get("human_review_content_sha256") == archive_only_form.get("content_sha256")
        and archive_only_item.get("review_status") == "human-reviewed-archive-only"
        and pending_count("after_archive") == pending_count("after_accept") - 1
        and pending_count("archive_drift_status")
        == pending_count("after_archive") + 1
        and any(
            row.get("id") == archive_only_item_id
            and "unresolved-content-sha256-drift" in row.get("reasons", [])
            for row in archive_drift_rows
        )
        and archive_drift_check_result["exit_code"] != 0
        and f"items:{archive_only_item_id} human review content drift" in archive_drift_check_result["stdout"],
        "review-queue-apply-tool-contract",
        "review queue apply validates and applies filled forms without owner-gate mutation",
        {
            "forms_exit_code": forms_result["exit_code"],
            "parse_errors": parse_errors,
            "before_exit_code": before_status_result["exit_code"],
            "before_pending": pending_count("before"),
            "dry_run_exit_code": dry_run_result["exit_code"],
            "dry_run_payload": payloads.get("dry_run", {}),
            "forbidden_exit_code": forbidden_result["exit_code"],
            "forbidden_codes": forbidden_codes,
            "stale_date_exit_code": stale_date_result["exit_code"],
            "stale_date_codes": stale_date_codes,
            "hash_mismatch_exit_code": hash_mismatch_result["exit_code"],
            "hash_mismatch_codes": hash_mismatch_codes,
            "archive_only_payload": payloads.get("archive_only", {}),
            "apply_exit_code": apply_result["exit_code"],
            "after_accept_pending": pending_count("after_accept"),
            "drift_pending": pending_count("drift_status"),
            "drift_check_exit_code": drift_check_result["exit_code"],
            "needs_edits_apply_exit_code": needs_edits_apply_result["exit_code"],
            "after_needs_edits_pending": pending_count("after_needs_edits"),
            "archive_only_apply_exit_code": archive_only_apply_result["exit_code"],
            "after_archive_pending": pending_count("after_archive"),
            "archive_drift_pending": pending_count("archive_drift_status"),
            "archive_drift_check_exit_code": archive_drift_check_result["exit_code"],
            "accept_item": accept_item,
            "needs_edits_item": needs_edits_item,
            "archive_only_item": archive_only_item,
        },
        repo,
    )

def test_summary_backfill_archived_only_contract():
    repo = copy_repo("summary-backfill")
    items_path = repo / "registry" / "items.jsonl"
    target_archived = "knowledge-hub-archived-summary-full-closeout-20260711"
    target_active = "knowledge-hub-root"
    target_reviewing = "pcr02-camera-raw-preview-virtual-stream-architecture-20260711"
    artifact_id = "knowledge-hub-summary-backfill-regression-closeout-20260711"
    md_path = repo / "artifacts" / "manifests" / f"{artifact_id}.md"
    jsonl_path = repo / "artifacts" / "manifests" / f"{artifact_id}.jsonl"

    rows = []
    seen = set()
    for line in items_path.read_text().splitlines():
        if not line.strip():
            continue
        row = json.loads(line)
        if row.get("id") in {target_archived, target_active, target_reviewing}:
            row.pop("summary_zh", None)
            seen.add(row.get("id"))
        rows.append(row)
    items_path.write_text("\n".join(json.dumps(row, ensure_ascii=False, separators=(",", ":")) for row in rows) + "\n")
    before_hash = hashlib.sha256(items_path.read_bytes()).hexdigest()

    dry_run = run_cmd(
        repo,
        [
            "rtk",
            "bash",
            "tools/knowledge-summary-backfill.sh",
            "--as-of",
            today.isoformat(),
            "--artifact-id",
            artifact_id,
            "--json",
        ],
    )
    after_dry_hash = hashlib.sha256(items_path.read_bytes()).hexdigest()
    dry_md_exists = md_path.exists()
    dry_jsonl_exists = jsonl_path.exists()
    apply_result = run_cmd(
        repo,
        [
            "rtk",
            "bash",
            "tools/knowledge-summary-backfill.sh",
            "--apply",
            "--as-of",
            today.isoformat(),
            "--artifact-id",
            artifact_id,
            "--json",
        ],
    )

    parse_errors = []
    try:
        dry_payload = json.loads(dry_run["stdout"])
    except Exception as exc:
        dry_payload = {}
        parse_errors.append(f"dry_run: {exc}")
    try:
        apply_payload = json.loads(apply_result["stdout"])
    except Exception as exc:
        apply_payload = {}
        parse_errors.append(f"apply: {exc}")

    items_by_id = {}
    for line in items_path.read_text().splitlines():
        if line.strip():
            row = json.loads(line)
            items_by_id[row.get("id")] = row

    index_texts = {
        "by-owner": (repo / "indexes" / "by-owner.md").read_text(),
        "by-status": (repo / "indexes" / "by-status.md").read_text(),
        "by-review-date": (repo / "indexes" / "by-review-date.md").read_text(),
        "by-decision": (repo / "indexes" / "by-decision.md").read_text(),
    }
    index_refs_present = all(artifact_id in text for text in index_texts.values())
    artifact_json = {}
    try:
        artifact_json = json.loads(jsonl_path.read_text())
    except Exception as exc:
        parse_errors.append(f"artifact_jsonl: {exc}")

    expect(
        seen == {target_archived, target_active, target_reviewing}
        and dry_run["exit_code"] == 0
        and dry_payload.get("mode") == "dry-run"
        and dry_payload.get("selected_count") == 1
        and dry_payload.get("updated_ids") == [target_archived]
        and before_hash == after_dry_hash
        and not dry_md_exists
        and not dry_jsonl_exists
        and apply_result["exit_code"] == 0
        and apply_payload.get("mode") == "apply"
        and apply_payload.get("selected_count") == 1
        and apply_payload.get("updated_ids") == [target_archived]
        and items_by_id.get(target_archived, {}).get("summary_zh")
        and not items_by_id.get(target_active, {}).get("summary_zh")
        and not items_by_id.get(target_reviewing, {}).get("summary_zh")
        and items_by_id.get(artifact_id, {}).get("status") == "archived"
        and md_path.exists()
        and jsonl_path.exists()
        and artifact_json.get("artifact_id") == artifact_id
        and artifact_json.get("selected_count") == 1
        and index_refs_present
        and not parse_errors,
        "summary-backfill-archived-only-contract",
        "summary backfill dry-run is no-write and apply only updates archived missing summaries",
        {
            "seen": sorted(seen),
            "dry_exit_code": dry_run["exit_code"],
            "apply_exit_code": apply_result["exit_code"],
            "dry_payload": dry_payload,
            "apply_payload": apply_payload,
            "before_hash": before_hash,
            "after_dry_hash": after_dry_hash,
            "dry_md_exists": dry_md_exists,
            "dry_jsonl_exists": dry_jsonl_exists,
            "active_summary_present": bool(items_by_id.get(target_active, {}).get("summary_zh")),
            "reviewing_summary_present": bool(items_by_id.get(target_reviewing, {}).get("summary_zh")),
            "index_refs_present": index_refs_present,
            "parse_errors": parse_errors,
        },
        repo,
    )

def test_orphan_files_advisory_contract():
    repo = copy_repo("orphan-files")
    git_setup = init_temp_git_repo(repo)
    git_config = run_cmd(
        repo,
        ["rtk", "git", "config", "status.showUntrackedFiles", "no"],
    )
    deleted_rel = "governance/deleted-orphan-regression-fixture.md"
    deleted_path = repo / deleted_rel
    deleted_path.write_text("# Deleted orphan regression fixture\n")
    git_add = run_cmd(repo, ["rtk", "git", "add", deleted_rel])
    git_commit = run_cmd(
        repo,
        [
            "rtk",
            "git",
            "-c",
            "user.name=Knowledge Hub Regression",
            "-c",
            "user.email=regression@knowledge-hub.local",
            "commit",
            "-m",
            "test: track deleted orphan fixture",
        ],
    )
    deleted_path.unlink()
    deleted_candidate = run_cmd(
        repo,
        [
            "rtk",
            "bash",
            "tools/knowledge-orphan-files.sh",
            "--strict",
            "--json",
        ],
    )
    baseline = run_cmd(
        repo,
        [
            "rtk",
            "bash",
            "tools/knowledge-orphan-files.sh",
            "--all",
            "--strict",
            "--json",
            "--limit",
            "20",
        ],
    )
    orphan_rel = "projects/xcrz-sigmastar-demo/archive/debug/orphan-regression-fixture.md"
    orphan_path = repo / orphan_rel
    orphan_path.parent.mkdir(parents=True, exist_ok=True)
    orphan_path.write_text("# Orphan regression fixture\n\nThis file intentionally has no registry item.\n")

    advisory = run_cmd(
        repo,
        [
            "rtk",
            "bash",
            "tools/knowledge-orphan-files.sh",
            "--all",
            "--json",
            "--limit",
            "500",
        ],
    )
    strict = run_cmd(
        repo,
        [
            "rtk",
            "bash",
            "tools/knowledge-orphan-files.sh",
            "--all",
            "--strict",
            "--json",
            "--limit",
            "500",
        ],
    )
    parse_errors = []
    try:
        deleted_candidate_payload = json.loads(deleted_candidate["stdout"])
    except Exception as exc:
        deleted_candidate_payload = {}
        parse_errors.append(f"deleted-candidate: {exc}")
    try:
        baseline_payload = json.loads(baseline["stdout"])
    except Exception as exc:
        baseline_payload = {}
        parse_errors.append(f"baseline: {exc}")
    try:
        advisory_payload = json.loads(advisory["stdout"])
    except Exception as exc:
        advisory_payload = {}
        parse_errors.append(f"advisory: {exc}")
    try:
        strict_payload = json.loads(strict["stdout"])
    except Exception as exc:
        strict_payload = {}
        parse_errors.append(f"strict: {exc}")

    frontmatter_path = repo / "governance" / "obsidian-integration.md"
    frontmatter_text = frontmatter_path.read_text()
    frontmatter_path.write_text(frontmatter_text.replace("status: reviewing", "status: active", 1))
    artifact_manifest = repo / "artifacts" / "manifests" / "patent-disclosure-artifact-ref-20260619.jsonl"
    required_artifact = None
    for line in artifact_manifest.read_text().splitlines():
        row = json.loads(line)
        if row.get("vault_presence", "required") == "required":
            required_artifact = repo / "artifacts" / "vault" / "patent-disclosure" / row["source_path"]
            break
    if required_artifact is not None:
        required_artifact.unlink()
    negative_check = run_cmd(
        repo,
        [
            "rtk",
            "bash",
            "tools/knowledge-check.sh",
            "--dry-run",
            "--json",
            "--diagnostics",
            "--as-of",
            "2026-07-13",
        ],
    )
    try:
        negative_payload = json.loads(negative_check["stdout"])
    except Exception as exc:
        negative_payload = {}
        parse_errors.append(f"negative-check: {exc}")
    negative_categories = {
        row.get("id")
        for row in negative_payload.get("diagnostics", {}).get("categories", [])
        if isinstance(row, dict)
    }

    expect(
        not git_setup
        and git_config["exit_code"] == 0
        and git_add["exit_code"] == 0
        and git_commit["exit_code"] == 0
        and deleted_candidate["exit_code"] == 0
        and deleted_candidate_payload.get("status") == "ok"
        and deleted_rel not in deleted_candidate_payload.get("missing_registry", [])
        and baseline["exit_code"] == 0
        and baseline_payload.get("status") == "ok"
        and baseline_payload.get("missing_registry_count") == 0
        and baseline_payload.get("collection_covered_count", 0) > 0
        and baseline_payload.get("coverage_contract_status") == "pass"
        and advisory["exit_code"] == 0
        and strict["exit_code"] == 1
        and advisory_payload.get("mode") == "all"
        and advisory_payload.get("status") == "needs-fix"
        and orphan_rel in advisory_payload.get("missing_registry", [])
        and strict_payload.get("strict") is True
        and orphan_rel in strict_payload.get("missing_registry", [])
        and negative_check["exit_code"] == 1
        and {"frontmatter-status", "artifact-vault"}.issubset(negative_categories)
        and not parse_errors,
        "orphan-files-advisory-contract",
        "frozen body coverage passes at baseline while orphan, frontmatter drift and missing vault files fail closed",
        {
            "baseline_exit_code": baseline["exit_code"],
            "git_setup": git_setup,
            "git_config_exit_code": git_config["exit_code"],
            "git_add_exit_code": git_add["exit_code"],
            "git_commit_exit_code": git_commit["exit_code"],
            "deleted_candidate_exit_code": deleted_candidate["exit_code"],
            "deleted_candidate_status": deleted_candidate_payload.get("status"),
            "deleted_candidate_missing_registry": deleted_candidate_payload.get("missing_registry"),
            "baseline_status": baseline_payload.get("status"),
            "baseline_exact_registered_count": baseline_payload.get("exact_registered_count"),
            "baseline_collection_covered_count": baseline_payload.get("collection_covered_count"),
            "baseline_coverage_contract_status": baseline_payload.get("coverage_contract_status"),
            "advisory_exit_code": advisory["exit_code"],
            "strict_exit_code": strict["exit_code"],
            "advisory_missing_registry": advisory_payload.get("missing_registry"),
            "strict_missing_registry": strict_payload.get("missing_registry"),
            "strict_coverage_contract_status": strict_payload.get("coverage_contract_status"),
            "negative_check_exit_code": negative_check["exit_code"],
            "negative_categories": sorted(negative_categories),
            "parse_errors": parse_errors,
        },
        repo,
    )

